#include <bits/stdc++.h>
using namespace std;
int main() {

    int n, x, y, ans;
    cin >> n >> x >> y;
    assert(1 <= n && n <= 1000 && 1 <= x && x <= 1000 && 1 <= y && y <= 1000);
    ans = n - y / x - 1 + (y % x == 0);
    assert(ans >= 1);
    cout << ans << '\n';

    return 0;
}

#include <bits/stdc++.h>
using namespace std;
int main() {

    int n; cin >> n; assert(1 <= n && n <= 100);
    for (int i = 1, x; i <= n; i ++) {
        cin >> x; assert(1 <= x && x <= 10000);
        cout << (x + 5) / 10 * 10 << '\n';
    }

    return 0;
}
